def gaps(postings):
    res = []
    last = 0
    for p in postings:
        res.append(p - last)
        last = p
    return res
def vb_encode(n):
    bytes = []
    while True:
        bytes.insert(0, n % 128)
        n = n // 128
        if n == 0:
            break
    bytes[-1] = bytes[-1] + 128
    return bytes
def vb_encode_list(postings):
    gap_list = gaps(postings)
    all_bytes = []
    for g in gap_list:
        all_bytes.extend(vb_encode(g))
    return all_bytes
def vb_decode(bytes_list):
    nums = []
    n = 0
    for b in bytes_list:
        if b < 128:
            n = 128 * n + b
        else:
            n = 128 * n + (b - 128)
            nums.append(n)
            n = 0
    return nums
print(vb_encode(130))

